<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/report_tools.php';
requireModuleAccess('trial_balance');
$ready=(bool)$conn->query("SHOW TABLES LIKE 'journal_lines'")->fetchColumn()&&(bool)$conn->query("SHOW TABLES LIKE 'journal_entries'")->fetchColumn();
$asAt=$_GET['as_at']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$asAt))$asAt=date('Y-m-d');
$rows=[];$debitTotal=0.0;$creditTotal=0.0;$difference=0.0;
if($ready){$q=$conn->prepare("SELECT a.id,a.account_code,a.account_name,a.account_type,COALESCE(SUM(CASE WHEN j.id IS NOT NULL THEN l.debit ELSE 0 END),0) debit,COALESCE(SUM(CASE WHEN j.id IS NOT NULL THEN l.credit ELSE 0 END),0) credit FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journal_entries j ON j.id=l.journal_entry_id AND j.status='Posted' AND j.journal_date<=? WHERE a.status='Active' GROUP BY a.id,a.account_code,a.account_name,a.account_type ORDER BY a.account_code");$q->execute([$asAt]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row){$net=(float)$row['debit']-(float)$row['credit'];$normalDebit=in_array($row['account_type'],['Asset','Expense'],true);$balance=$normalDebit?$net:-$net;$row['balance_debit']=max(0,$balance);$row['balance_credit']=max(0,-$balance);$debitTotal+=$row['balance_debit'];$creditTotal+=$row['balance_credit'];}unset($row);$difference=round($debitTotal-$creditTotal,2);}
$exportRows=[];foreach($rows as $row){if((float)$row['balance_debit']===0.0&&(float)$row['balance_credit']===0.0)continue;$exportRows[]=[$row['account_code'],$row['account_name'],$row['account_type'],$row['balance_debit'],$row['balance_credit']];}dibonkeReportExport('trial_balance_as_at_'.$asAt,['Account Code','Account Name','Account Type','Debit','Credit'],$exportRows);
$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="content"><?php dibonkeReportPrintStyles(); ?><style>
.tb-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.tb-tabs a{padding:9px 12px;background:#edf2f7;border-radius:8px;text-decoration:none;color:#17324d;font-size:12px;font-weight:800}.tb-panel{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;margin:14px 0}.tb-btn{background:#174a7e;color:#fff;border:0;border-radius:7px;padding:9px 14px;font-weight:800}.tb-table{width:100%;border-collapse:collapse}.tb-table th,.tb-table td{padding:9px;border-bottom:1px solid #edf1f5;text-align:left;font-size:12px}.tb-table th{background:#f3f6fa}.num{text-align:right!important;white-space:nowrap}.muted{color:#64748b}.tb-total{font-size:18px;font-weight:900;color:#17324d}
</style>
<h1>Trial Balance</h1><p class="muted">Balances from posted double-entry journals only. Draft entries are excluded.</p><nav class="tb-tabs"><a href="chart_of_accounts.php">Chart of Accounts</a><a href="journals.php">Journal Entries</a><a href="general_ledger.php">General Ledger</a><a href="trial_balance.php">Trial Balance</a><a href="periods.php">Period Controls</a></nav>
<?php if(!$ready):?><section class="tb-panel">Import the double-entry accounting migration first.</section><?php else:?><section class="tb-panel"><form method="get">As at <input type="date" name="as_at" value="<?=e($asAt)?>"> <button class="tb-btn">Generate</button></form><?php dibonkeReportActions('trial_balance'); ?><p>As at <?=e($asAt)?></p><div style="overflow:auto"><table class="tb-table"><thead><tr><th>Account code</th><th>Account name</th><th>Type</th><th class="num">Debit (<?=e($currency)?>)</th><th class="num">Credit (<?=e($currency)?>)</th></tr></thead><tbody><?php foreach($rows as $row):if((float)$row['balance_debit']===0.0&&(float)$row['balance_credit']===0.0)continue;?><tr><td><?=e($row['account_code'])?></td><td><?=e($row['account_name'])?></td><td><?=e($row['account_type'])?></td><td class="num"><?=number_format((float)$row['balance_debit'],2)?></td><td class="num"><?=number_format((float)$row['balance_credit'],2)?></td></tr><?php endforeach;?><tr><th colspan="3">Total</th><th class="num tb-total"><?=number_format($debitTotal,2)?></th><th class="num tb-total"><?=number_format($creditTotal,2)?></th></tr></tbody></table></div><p><strong>Difference:</strong> <?=e($currency)?> <?=number_format(abs($difference),2)?> <?=$difference===0.0?'— Balanced':'— Out of balance'?></p><?php if(abs($difference)>0.009):?><p class="muted">Investigate opening balances or any historical journals before relying on this report. Only posted journals are included.</p><?php endif;?></section><?php endif;?></main><?php require_once __DIR__.'/../../includes/footer.php';?>
